468	export function parseExecutableScenarioManifest(
469	  value: unknown,
470	  sourceLabel?: string,
471	): ExecutableScenarioManifest {
472	  const issues: ManifestIssue[] = [];
473	  if (!isPlainRecord(value)) {
474	    throw new ManifestValidationError(
475	      [{ path: "$", message: "must be a plain record" }],
476	      sourceLabel,
477	    );
478	  }
479	  reportUnknownKeys(value, ROOT_KEYS, "$", issues);
480	  const version = ownValue(value, "manifestVersion");
481	  if (version !== 1 && version !== 2)
482	    issues.push({ path: "$.manifestVersion", message: "must equal 1 or 2" });
483	  const catalogId = readId(ownValue(value, "catalogId"), "$.catalogId", issues);
484	  const scenariosValue = ownValue(value, "scenarios");
485	  const scenarios: ExecutableScenario[] = [];
486	  const ids = new Set<string>();
487	  if (!Array.isArray(scenariosValue)) {
488	    issues.push({ path: "$.scenarios", message: "must be an array" });
489	  } else {
490	    for (const [index, candidate] of scenariosValue.entries()) {
491	      const scenario = parseScenario(
492	        candidate,
493	        `$.scenarios[${index}]`,
494	        issues,
495	        version === 2 ? 2 : 1,
496	      );
497	      if (scenario === undefined) continue;
498	      if (ids.has(scenario.id))
499	        issues.push({ path: `$.scenarios[${index}].id`, message: "must be unique" });
500	      else ids.add(scenario.id);
501	      scenarios.push(scenario);
502	    }
503	  }
504	  if (issues.length > 0) throw new ManifestValidationError(issues, sourceLabel);
505	  return {
506	    manifestVersion: version as ExecutableManifestVersion,
507	    catalogId: catalogId as string,
508	    scenarios,
509	  };
510	}
