512	function parseScenario(
513	  value: unknown,
514	  path: string,
515	  issues: ManifestIssue[],
516	  version: ExecutableManifestVersion,
517	): ExecutableScenario | undefined {
518	  if (!isPlainRecord(value)) {
519	    issues.push({ path, message: "must be a plain record" });
520	    return undefined;
521	  }
522	  reportUnknownKeys(value, SCENARIO_KEYS, path, issues);
523	  const id = readId(ownValue(value, "id"), `${path}.id`, issues);
524	  const requiredProfile = readProfile(
525	    ownValue(value, "requiredProfile"),
526	    `${path}.requiredProfile`,
527	    issues,
528	  );
529	  const setup = parseSetup(ownValue(value, "setup"), `${path}.setup`, issues);
530	  const applicability = parseApplicability(
531	    ownValue(value, "applicability"),
532	    `${path}.applicability`,
533	    issues,
534	  );
535	  const requestsValue = ownValue(value, "requests");
536	  const actionsValue = ownValue(value, "actions");
537	  const hasRequests = requestsValue !== undefined;
538	  const hasActions = actionsValue !== undefined;
539	  if (hasRequests === hasActions)
540	    issues.push({ path, message: "must choose exactly one of requests or actions" });
541	  const requests = hasRequests
542	    ? parseRequests(requestsValue, `${path}.requests`, issues, requiredProfile, version)
543	    : undefined;
544	  const actions = hasActions
545	    ? parseActions(actionsValue, `${path}.actions`, issues, requiredProfile, version)
546	    : undefined;
547	  const cleanup = parseCleanup(ownValue(value, "cleanup"), `${path}.cleanup`, issues);
548	  if (
549	    id === undefined ||
550	    requiredProfile === undefined ||
551	    setup === undefined ||
552	    applicability === undefined ||
553	    hasRequests === hasActions ||
554	    (hasRequests && requests === undefined) ||
555	    (hasActions && actions === undefined) ||
556	    cleanup === undefined
557	  )
558	    return undefined;
559	  return hasRequests
560	    ? {
561	        id,
562	        requiredProfile,
563	        setup,
564	        applicability,
565	        requests: requests as ScenarioRequest[],
566	        cleanup,
567	      }
568	    : { id, requiredProfile, setup, applicability, actions: actions as ScenarioAction[], cleanup };
