641	    const negativeMethodProbe = negativeMethodProbeValue === true ? true : undefined;
642	    if (negativeMethodProbeValue !== undefined && negativeMethodProbeValue !== true)
643	      issues.push({ path: `${requestPath}.negativeMethodProbe`, message: "must equal true" });
644	    if (requiredProfile === "read" && method !== undefined) {
645	      const ordinaryReadMethod = method === "GET" || method === "HEAD" || method === "OPTIONS";
646	      if (ordinaryReadMethod && negativeMethodProbe === true)
647	        issues.push({
648	          path: `${requestPath}.negativeMethodProbe`,
649	          message: "is only valid for the explicit POST 405 probe",
650	        });
651	      if (!ordinaryReadMethod && !(method === "POST" && negativeMethodProbe === true))
652	        issues.push({
653	          path: `${requestPath}.method`,
