660	      issues,
661	    );
662	    const target = parseTarget(ownValue(candidate, "target"), `${requestPath}.target`, issues);
663	    const input = parseRequestInput(
664	      candidate,
665	      requestPath,
666	      issues,
667	      priorRequestIds,
668	      version,
669	      requiredProfile,
670	    );
671	    const captures = parseCaptures(
672	      ownValue(candidate, "captures"),
673	      `${requestPath}.captures`,
674	      issues,
675	    );
676	    const assertions = parseAssertions(
677	      ownValue(candidate, "assertions"),
678	      `${requestPath}.assertions`,
679	      issues,
680	      version,
681	    );
682	    validateRequestAssertions(assertions, input, requestPath, issues);
683	    validateEarlierResponseAssertions(
684	      assertions,
685	      priorRequestIds,
686	      method,
687	      `${requestPath}.assertions`,
688	      issues,
689	    );
690	    if (
691	      id === undefined ||
692	      method === undefined ||
693	      target === undefined ||
694	      input === undefined ||
695	      captures === undefined ||
696	      assertions === undefined
