698	      continue;
699	    const parsedRequest = {
700	      id,
701	      method,
702	      target,
703	      ...(prerequisiteScenario === undefined ? {} : { prerequisiteScenario }),
704	      ...input,
705	      ...(negativeMethodProbe === undefined ? {} : { negativeMethodProbe }),
706	      ...(rawRequestTarget === undefined ? {} : { rawRequestTarget }),
707	      captures,
708	      assertions,
709	    } satisfies ScenarioRequest;
710	    validatePriorCaptureAssertions(assertions, establishedBindings, requestPath, issues);
711	    const requestBindings = new Set<string>();
712	    for (const [captureIndex, capture] of captures.entries()) {
713	      if (requestBindings.has(capture.binding)) continue;
