2473	): string {
2474	  let value: unknown;
2475	  if (capture.from.kind === "response-url") value = response.url;
2476	  else if (capture.from.kind === "header-link")
2477	    value = linkHeader(response.headers.link, capture.from.rel, response.url);
2478	  else {
